@Service
public class KPIService 
		extends BaseService {
//************************************************************************
// Public Methods
//************************************************************************
	/**
	 * Default Constructor
	 */
    public KPIService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new KPIEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(KPIRepository.class) );
		this.validator		= applicationContext.getBean(KPIValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		KPI
	 */
		public KPI createKPI( CreateKPICommand command ) {

		KPI entity = new KPI();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setKPIId( command.getKPIId() );
            entity.setTargetValue( command.getTargetValue() );
            entity.setMetricType( command.getMetricType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of KPI {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateKPICommand
	 * @return		KPI
	 */
	public KPI updateKPI( UpdateKPICommand command ) {

		KPI entity = new KPI();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setKPIId( command.getKPIId() );
            entity.setTargetValue( command.getTargetValue() );
            entity.setCampaign( command.getCampaign() );
            entity.setMetricType( command.getMetricType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of KPI {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteKPICommand
	 */
	public void delete( DeleteKPICommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getKPIId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of KPI {0} ", id );

	}

	/**
	 * Method to retrieve the KPI via KPIFetchOneSummary
	 * @param 	summary KPIFetchOneSummary
	 * @return 	KPIFetchOneResponse
	 */
	public KPI getKPI( KPIFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "KPIFetchOneSummary arg cannot be null" );

		KPI entity = null;
		UUID id = summary.getKPIId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a KPI using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all KPIs
	 *
	 * @return 	List<KPI>
	 */
    public List<KPI> getAllKPI() {
		List<KPI> list = projector.findAll( new FindAllKPIQuery() );
		return list;
	}

	/**
	 * assign Campaign on KPI
	 * @param		command AssignCampaignToKPICommand
	 */
	public void assignCampaign( AssignCampaignToKPICommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignCampaign(command.getKPIId(), command.getAssignment());

	}

	/**
	 * unAssign Campaign on KPI
	 * @param		command UnAssignCampaignFromKPICommand
	 */
	public void unAssignCampaign( UnAssignCampaignFromKPICommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignCampaign(command.getKPIId());
	}
	




//************************************************************************
// Attributes
//************************************************************************
	@Autowired
    private final KPIEntityProjector projector;
	private final KPIValidator validator;
	private KPI kPI 	= null;
	private CurrentIdentity identity			= null;
	private static final Logger LOGGER 			=  LoggerFactory.getLogger(KPIService.class);
}
